import{_ as r,o,c as a,a2 as d}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"从 brief 到成片：完整链路 SOP","description":"","frontmatter":{},"headers":[],"relativePath":"method/workflow-sop.md","filePath":"method/workflow-sop.md","lastUpdated":1786503105000}'),s={name:"method/workflow-sop.md"};function n(e,t,p,i,l,g){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="从-brief-到成片-完整链路-sop" tabindex="-1">从 brief 到成片：完整链路 SOP <a class="header-anchor" href="#从-brief-到成片-完整链路-sop" aria-label="Permalink to &quot;从 brief 到成片：完整链路 SOP&quot;">​</a></h1><p>一支 AI 广告的标准推进路径，六个阶段。每个阶段给出：<strong>输入 → 干什么 → 输出 → 谁来做</strong>。</p><p>照着走的价值在于，任何一步出问题都能定位到是哪个阶段的锅，而不是笼统地说「效果不好」。</p><h2 id="全局视图" tabindex="-1">全局视图 <a class="header-anchor" href="#全局视图" aria-label="Permalink to &quot;全局视图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 拆 brief  →  ② 找洞察  →  ③ 定 Big Idea  →  ④ 分镜  →  ⑤ 生成  →  ⑥ 合成</span></span>
<span class="line"><span>   人主导        人机协作       人主导          人机协作      AI 主导     人主导</span></span></code></pre></div><p>注意 AI 的参与度<strong>中间高、两头低</strong>。开头（想清楚说什么）和结尾（品控）是人的战场。</p><hr><h2 id="_1-拆-brief" tabindex="-1">① 拆 brief <a class="header-anchor" href="#_1-拆-brief" aria-label="Permalink to &quot;① 拆 brief&quot;">​</a></h2><p><strong>输入</strong>：客户的一段话、一份 PPT，或者只有一句「帮我做个推广视频」。</p><p><strong>干什么</strong>：把模糊需求逼成六个确定的答案。</p><table tabindex="0"><thead><tr><th>问题</th><th>不合格的答案</th><th>合格的答案</th></tr></thead><tbody><tr><td>卖给谁</td><td>年轻人</td><td>一线城市 22–28 岁、刚工作、租房、通勤 40 分钟以上</td></tr><tr><td>说什么</td><td>我们产品很好</td><td>五分钟能做完一顿看起来不敷衍的早饭</td></tr><tr><td>为什么信</td><td>品质保证</td><td>独立包装、无需解冻、微波 3 分钟</td></tr><tr><td>在哪看到</td><td>网上</td><td>抖音信息流，竖屏，前 3 秒决定生死</td></tr><tr><td>看完做什么</td><td>提升品牌认知</td><td>点击购物车链接</td></tr><tr><td>有什么不能碰</td><td>——</td><td>不能出现明火、不能宣称减肥功效</td></tr></tbody></table><p><strong>输出</strong>：一页纸的需求确认单，最好客户签字。</p><p><strong>谁来做</strong>：人。AI 可以帮你把客户的原话整理成结构，但<strong>不能替你去问客户</strong>。这一步偷懒，后面全是返工。</p><div class="warning custom-block"><p class="custom-block-title">最容易翻车的地方</p><p>「在哪看到」经常被跳过。同一条创意，做成 16:9 横屏放贴片和做成 9:16 竖屏放信息流，分镜逻辑完全不同——竖屏必须在 3 秒内出钩子，横屏可以铺垫 8 秒。渠道决定结构，不是最后改个尺寸的事。</p></div><hr><h2 id="_2-找洞察" tabindex="-1">② 找洞察 <a class="header-anchor" href="#_2-找洞察" aria-label="Permalink to &quot;② 找洞察&quot;">​</a></h2><p><strong>输入</strong>：需求确认单。</p><p><strong>干什么</strong>：找到目标人群一个<strong>真实存在、没被说破</strong>的心理。</p><p>洞察不是产品卖点的换句话说。「我们的速食早餐很方便」是卖点；「早上多睡十分钟的幸福感，值得用一顿敷衍的早饭去换，但我不想承认自己在敷衍」是洞察。</p><p><strong>AI 在这一步怎么用</strong>：让它当发散器，不当决策器。</p><p>有效的提问方式：</p><blockquote><p>我在做一款速食早餐的广告，目标人群是一线城市刚工作的年轻人。 请列出 20 条这群人在「早上」这个场景里可能有的、说不出口的真实心理。 要求：不要出现产品，不要正能量，越具体越好。允许负面、矛盾、不体面的心理。</p></blockquote><p>关键在于<strong>禁止它提产品</strong>。一旦允许提产品，AI 会立刻退回到卖点复述。</p><p><strong>输出</strong>：3–5 条候选洞察。</p><p><strong>谁来做</strong>：AI 发散 20 条，人从中挑出 3 条能打的。这个筛选动作是人的核心价值——AI 不知道哪条会让人心里&quot;咯噔&quot;一下。</p><p>详见 <a href="/method/big-idea">Big Idea 与洞察：AI 的能力边界</a>。</p><hr><h2 id="_3-定-big-idea" tabindex="-1">③ 定 Big Idea <a class="header-anchor" href="#_3-定-big-idea" aria-label="Permalink to &quot;③ 定 Big Idea&quot;">​</a></h2><p><strong>输入</strong>：选定的洞察。</p><p><strong>干什么</strong>：把洞察变成一个可执行的创意概念——一句话能说清、能画出画面的那种。</p><p>检验标准三条：</p><ol><li><strong>能一句话讲完</strong>，讲的时候对方眼睛会亮一下。</li><li><strong>能画出至少三个不同的画面</strong>，说明它有延展性，不是一个孤立的段子。</li><li><strong>换成竞品也成立吗？</strong> 如果成立，说明这个 idea 和你的产品没关系，废掉重来。</li></ol><p>第三条是最狠的筛子，能砍掉一大半自我感动的创意。</p><p><strong>输出</strong>：一句话的 Big Idea + 一句 slogan。</p><p><strong>谁来做</strong>：人主导。AI 可以在你有了方向后，帮你生成 20 个 slogan 变体供挑选。</p><hr><h2 id="_4-分镜" tabindex="-1">④ 分镜 <a class="header-anchor" href="#_4-分镜" aria-label="Permalink to &quot;④ 分镜&quot;">​</a></h2><p><strong>输入</strong>：Big Idea。</p><p><strong>干什么</strong>：把创意拆成 N 个可以被单独生成的镜头。</p><p>这是整条链路里<strong>最被低估</strong>的一步。大部分「AI 广告做出来很业余」的问题，根源都在这里——不是画面不好看，是镜头之间没有关系。</p><p>一个 15 秒竖屏视频的典型结构：</p><table tabindex="0"><thead><tr><th>秒数</th><th>镜头</th><th>任务</th></tr></thead><tbody><tr><td>0–3</td><td>镜头 1</td><td>钩子。必须有异常感，让人手指停下来</td></tr><tr><td>3–7</td><td>镜头 2–3</td><td>共鸣。把洞察演出来，让人觉得「这就是我」</td></tr><tr><td>7–11</td><td>镜头 4–5</td><td>转折。产品出现，给出解法</td></tr><tr><td>11–15</td><td>镜头 6</td><td>落点。slogan + 行动指令</td></tr></tbody></table><p>每个镜头要写清楚：<strong>景别、机位、主体动作、环境、光线、时长</strong>。写不清楚就别往下走，因为下一步 AI 只能按你写的画。</p><p><strong>输出</strong>：一张分镜表。</p><p><strong>谁来做</strong>：人定结构，AI 填细节。具体的词表见 <a href="/method/storyboard">分镜设计</a>。</p><hr><h2 id="_5-生成" tabindex="-1">⑤ 生成 <a class="header-anchor" href="#_5-生成" aria-label="Permalink to &quot;⑤ 生成&quot;">​</a></h2><p><strong>输入</strong>：分镜表。</p><p><strong>干什么</strong>：逐镜头生成素材。</p><p>工作方式是<strong>并行 + 批量</strong>，不是一个镜头死磕到完美再做下一个。原因：单镜头看着好，串起来风格可能对不上。正确顺序是——</p><ol><li>先用同一套风格描述，把所有镜头各生成一版，拼起来看整体调性。</li><li>调性对了，再挑质量不达标的单镜头重做。</li><li>全部达标后，每个关键镜头多生成 2–3 个备选，给剪辑留余地。</li></ol><p><strong>废片率预期</strong>：做 6 个镜头，生成 30–50 条素材属于正常。把这个消耗算进报价里。</p><p><strong>输出</strong>：分镜头素材包 + 备选。</p><p><strong>谁来做</strong>：AI 主导，人做筛选。工具选择见 <a href="/tools/">工具地图</a>。</p><div class="tip custom-block"><p class="custom-block-title">一致性的实操要点</p><p>把风格描述固定成一段文本，每个镜头的 Prompt 都原样带上这段，只改主体和动作。人物、产品用同一张参考图贯穿。风格描述中途改一个词，整支片子的调性就会飘。</p></div><hr><h2 id="_6-合成" tabindex="-1">⑥ 合成 <a class="header-anchor" href="#_6-合成" aria-label="Permalink to &quot;⑥ 合成&quot;">​</a></h2><p><strong>输入</strong>：素材包。</p><p><strong>干什么</strong>：剪辑、调色、配音、加字幕、导出。</p><p>AI 能做粗剪，但<strong>精修仍然靠传统软件</strong>。这一步的价值在于把一堆&quot;还行&quot;的素材，通过节奏和调色统一成一支&quot;完整&quot;的片子。</p><p>必查清单：</p><ul><li>[ ] 前 3 秒是否成立（关掉声音也要成立）</li><li>[ ] 全片色调是否统一（AI 素材常有色温漂移，统一调色能救回很多）</li><li>[ ] 口播和字幕是否一致</li><li>[ ] 品牌元素（logo、色、slogan）是否准确</li><li>[ ] 有没有多余的帧——AI 视频常在结尾有半秒的诡异变形，剪掉</li><li>[ ] 导出规格是否符合投放平台要求</li></ul><p><strong>输出</strong>：成片。</p><p><strong>谁来做</strong>：人。</p><hr><h2 id="时间分配参考" tabindex="-1">时间分配参考 <a class="header-anchor" href="#时间分配参考" aria-label="Permalink to &quot;时间分配参考&quot;">​</a></h2><p>一个「15 秒竖屏短视频」的项目，三天工期的合理分配：</p><table tabindex="0"><thead><tr><th>阶段</th><th>占比</th><th>备注</th></tr></thead><tbody><tr><td>①–③ 想清楚</td><td>40%</td><td>最值得花时间的地方</td></tr><tr><td>④ 分镜</td><td>15%</td><td>想清楚了，分镜写得很快</td></tr><tr><td>⑤ 生成</td><td>25%</td><td>大量等待，可以并行做别的</td></tr><tr><td>⑥ 合成</td><td>20%</td><td>含反复微调</td></tr></tbody></table><p>新手常见的分配是 10% / 5% / 70% / 15% ——把绝大部分时间花在反复重生成上。那不是在做广告，是在抽卡。<strong>重生成次数过多，通常意味着前面某一步没想清楚。</strong></p>`,69)])])}const c=r(s,[["render",n]]);export{b as __pageData,c as default};
